-- Draftly — load 5 demo resume versions into one real account.
--
-- Each is a full, different resume (General, Backend, Frontend, Data,
-- Cloud & DevOps), each with its own template, built from the same facts as
-- the demo block bank (supabase/seed/demo_bank.sql). They appear in the
-- Versions panel and can be picked as "Resume used" in the job tracker.
--
-- How to run: Supabase dashboard → SQL Editor → New query → paste this file,
-- replace YOUR_EMAIL_HERE with the email you sign in with, and click Run.
-- Only that account is touched. Insert only: no other user's rows, and no
-- resumes, applications or saved blocks, are read or changed.
--
-- Safe to re-run: a version whose label that account already has is skipped.
-- To undo (versions not linked to an application):
--   delete from public.resume_versions
--   where user_id = (select id from auth.users where email = 'YOUR_EMAIL_HERE')
--     and label in ('General SWE — v2', 'Backend-focused', 'Frontend-focused', 'Data-focused', 'Cloud & DevOps')
--     and created_at > now() - interval '30 days';
--
-- The SQL editor runs as the database owner, so row-level security does not
-- apply here and user_id has to be set explicitly. Each snapshot is pointed
-- at the account's live resume, so restoring one replaces that resume's
-- content (and can be undone in the app).

with me as (
  select id from auth.users where email = 'YOUR_EMAIL_HERE'
),
live as (
  select r.id from public.resumes r, me where r.user_id = me.id order by r.created_at limit 1
),
versions (label, snapshot, days_ago) as (
  values
  ('General SWE — v2', '{"id":"r1","title":"General SWE — v2","templateId":"classic","profile":{"name":"Jordan Avery Chen","title":"Software Engineer","email":"jordan.chen@email.com","phone":"(214) 555-0182","location":"Arlington, TX","links":"github.com/jachen · linkedin.com/in/jachen"},"blocks":[{"id":"b1","type":"summary","label":"Summary","enabled":true,"data":{"text":"Computer science student with internship experience building web applications end to end. Comfortable across the stack, from Postgres schemas to React interfaces, and happiest shipping features other people actually use."}},{"id":"b2","type":"experience","label":"Experience","enabled":true,"data":{"items":[{"role":"Software Engineering Intern","org":"Northbridge Labs","dates":"Summer 2025","points":["Built a job-application tracker feature used by 400+ beta users, cutting manual status updates by 60%.","Wrote the REST endpoints and Postgres schema behind it, plus the React front end.","Added integration tests that caught three regressions before release."]},{"role":"Web Developer (Part-time)","org":"University IT Office","dates":"2024 – Present","points":["Maintain the university''s public site in a CMS with hand-written HTML, CSS, and JavaScript.","Fixed 20+ accessibility issues to meet WCAG AA, improving audit scores across key pages."]}]}},{"id":"b3","type":"skills","label":"Skills","enabled":true,"data":{"groups":[{"name":"Languages","items":"TypeScript, Python, Java, SQL"},{"name":"Frameworks","items":"React, FastAPI, Spring Boot"},{"name":"Tools","items":"Git, Docker, Supabase, Postgres"}]}},{"id":"b4","type":"education","label":"Education","enabled":true,"data":{"items":[{"school":"University of Texas at Arlington","degree":"B.S. Computer Science","dates":"Expected May 2027","detail":"Relevant coursework: Software Engineering, Databases, Computer Networks."}]}},{"id":"b5","type":"projects","label":"Projects","enabled":false,"data":{"items":[{"name":"Draftly","detail":"Block-based resume editor with drag-and-drop sections and application tracking. React, TypeScript, Supabase.","url":"github.com/jachen/draftly"}]}}]}'::jsonb, 5),
  ('Backend-focused', '{"id":"r1","title":"Backend-focused","templateId":"modern","profile":{"name":"Jordan Avery Chen","title":"Software Engineer","email":"jordan.chen@email.com","phone":"(214) 555-0182","location":"Arlington, TX","links":"github.com/jachen · linkedin.com/in/jachen"},"blocks":[{"id":"b1","type":"summary","label":"Summary","enabled":true,"data":{"text":"Computer science student who builds back ends: the REST endpoints and Postgres schema behind a feature used by 400+ beta users at Northbridge Labs, JUnit autograders as a Java TA, and a Terraform-provisioned Kubernetes homelab on AWS."}},{"id":"b2","type":"experience","label":"Experience","enabled":true,"data":{"items":[{"role":"Software Engineering Intern","org":"Northbridge Labs","dates":"Summer 2025","points":["Built a job-application tracker feature used by 400+ beta users, cutting manual status updates by 60%.","Wrote the REST endpoints and Postgres schema behind it, plus the React front end.","Added integration tests that caught three regressions before release."]},{"role":"Teaching Assistant, Data Structures","org":"University of Texas at Arlington","dates":"Fall 2024 – Spring 2025","points":["Led weekly Java lab sessions for 40 students on trees, graphs and hashing.","Wrote JUnit autograder tests that cut grading time per assignment by half."]}]}},{"id":"b5","type":"projects","label":"Projects","enabled":true,"data":{"items":[{"name":"Kubernetes Homelab","detail":"Three-node cluster running Docker services, provisioned with Terraform on AWS and deployed by a GitHub Actions CI/CD pipeline."},{"name":"Draftly","detail":"Block-based resume editor with drag-and-drop sections and application tracking. React, TypeScript, Supabase.","url":"github.com/jachen/draftly"}]}},{"id":"b3","type":"skills","label":"Skills","enabled":true,"data":{"groups":[{"name":"Languages","items":"Java, Python, SQL, TypeScript"},{"name":"Frameworks","items":"Spring Boot, FastAPI, React"},{"name":"Tools","items":"Postgres, Docker, Git, Supabase"},{"name":"Cloud & DevOps","items":"AWS, Kubernetes, Terraform, GitHub Actions, Linux"}]}},{"id":"b4","type":"education","label":"Education","enabled":true,"data":{"items":[{"school":"University of Texas at Arlington","degree":"B.S. Computer Science","dates":"Expected May 2027","detail":"Relevant coursework: Software Engineering, Databases, Computer Networks."}]}}]}'::jsonb, 4),
  ('Frontend-focused', '{"id":"r1","title":"Frontend-focused","templateId":"elegant","profile":{"name":"Jordan Avery Chen","title":"Software Engineer","email":"jordan.chen@email.com","phone":"(214) 555-0182","location":"Arlington, TX","links":"github.com/jachen · linkedin.com/in/jachen"},"blocks":[{"id":"b1","type":"summary","label":"Summary","enabled":true,"data":{"text":"Front-end developer who ships accessible interfaces: React features for 400+ beta users at Northbridge Labs, 20+ WCAG AA fixes on the university site, and React Native screens for a fitness app."}},{"id":"b2","type":"experience","label":"Experience","enabled":true,"data":{"items":[{"role":"Software Engineering Intern","org":"Northbridge Labs","dates":"Summer 2025","points":["Built a job-application tracker feature used by 400+ beta users, cutting manual status updates by 60%.","Wrote the REST endpoints and Postgres schema behind it, plus the React front end.","Added integration tests that caught three regressions before release."]},{"role":"Web Developer (Part-time)","org":"University IT Office","dates":"2024 – Present","points":["Maintain the university''s public site in a CMS with hand-written HTML, CSS, and JavaScript.","Fixed 20+ accessibility issues to meet WCAG AA, improving audit scores across key pages."]},{"role":"Mobile Developer Intern","org":"Pixel Kite Studio","dates":"Spring 2024","points":["Shipped two React Native screens for an iOS and Android fitness app with a Firebase back end.","Fixed crash reports from Sentry, lowering the crash rate from 2.1% to 0.4%."]}]}},{"id":"b5","type":"projects","label":"Projects","enabled":true,"data":{"items":[{"name":"Draftly","detail":"Block-based resume editor with drag-and-drop sections and application tracking. React, TypeScript, Supabase.","url":"github.com/jachen/draftly"},{"name":"Campus Ride Share","detail":"React Native app with Firebase auth and the Google Maps API, used by 150 students during a pilot semester."}]}},{"id":"b3","type":"skills","label":"Skills","enabled":true,"data":{"groups":[{"name":"Languages","items":"TypeScript, JavaScript, HTML, CSS, SQL"},{"name":"Frameworks","items":"React, React Native, FastAPI"},{"name":"Tools","items":"Git, Docker, Supabase, Postgres"}]}},{"id":"b4","type":"education","label":"Education","enabled":true,"data":{"items":[{"school":"University of Texas at Arlington","degree":"B.S. Computer Science","dates":"Expected May 2027","detail":"Relevant coursework: Software Engineering, Databases, Computer Networks."}]}}]}'::jsonb, 3),
  ('Data-focused', '{"id":"r1","title":"Data-focused","templateId":"compact","profile":{"name":"Jordan Avery Chen","title":"Software Engineer","email":"jordan.chen@email.com","phone":"(214) 555-0182","location":"Arlington, TX","links":"github.com/jachen · linkedin.com/in/jachen"},"blocks":[{"id":"b1","type":"summary","label":"Summary","enabled":true,"data":{"text":"Computer science student who turns data into decisions: Tableau dashboards on SQL and pandas pipelines across 12 clinic sites at Lone Star Health, a PyTorch sentiment model at 89% accuracy, and Postgres schemas at Northbridge Labs."}},{"id":"b2","type":"experience","label":"Experience","enabled":true,"data":{"items":[{"role":"Data Analyst Intern","org":"Lone Star Health","dates":"Summer 2024","points":["Built Tableau dashboards on SQL and Python (pandas) pipelines that tracked clinic wait times across 12 sites.","Automated a weekly Excel report with Python, saving the operations team about 5 hours a week."]},{"role":"Software Engineering Intern","org":"Northbridge Labs","dates":"Summer 2025","points":["Built a job-application tracker feature used by 400+ beta users, cutting manual status updates by 60%.","Wrote the REST endpoints and Postgres schema behind it, plus the React front end.","Added integration tests that caught three regressions before release."]},{"role":"Teaching Assistant, Data Structures","org":"University of Texas at Arlington","dates":"Fall 2024 – Spring 2025","points":["Led weekly Java lab sessions for 40 students on trees, graphs and hashing.","Wrote JUnit autograder tests that cut grading time per assignment by half."]}]}},{"id":"b5","type":"projects","label":"Projects","enabled":true,"data":{"items":[{"name":"Review Sentiment Analyzer","detail":"Python and PyTorch NLP model served through a FastAPI endpoint; 89% accuracy on 50k product reviews."}]}},{"id":"b3","type":"skills","label":"Skills","enabled":true,"data":{"groups":[{"name":"Data","items":"pandas, NumPy, PyTorch, Tableau, Excel"},{"name":"Languages","items":"Python, SQL, Java, TypeScript"},{"name":"Tools","items":"Git, Docker, Supabase, Postgres"}]}},{"id":"b4","type":"education","label":"Education","enabled":true,"data":{"items":[{"school":"University of Texas at Arlington","degree":"B.S. Computer Science","dates":"Expected May 2027","detail":"Relevant coursework: Software Engineering, Databases, Computer Networks."}]}}]}'::jsonb, 2),
  ('Cloud & DevOps', '{"id":"r1","title":"Cloud & DevOps","templateId":"sidebar","profile":{"name":"Jordan Avery Chen","title":"Software Engineer","email":"jordan.chen@email.com","phone":"(214) 555-0182","location":"Arlington, TX","links":"github.com/jachen · linkedin.com/in/jachen"},"blocks":[{"id":"b1","type":"summary","label":"Summary","enabled":true,"data":{"text":"Computer science student focused on infrastructure: a three-node Kubernetes homelab provisioned with Terraform on AWS and deployed through GitHub Actions, plus production REST services and integration tests at Northbridge Labs."}},{"id":"b2","type":"experience","label":"Experience","enabled":true,"data":{"items":[{"role":"Software Engineering Intern","org":"Northbridge Labs","dates":"Summer 2025","points":["Built a job-application tracker feature used by 400+ beta users, cutting manual status updates by 60%.","Wrote the REST endpoints and Postgres schema behind it, plus the React front end.","Added integration tests that caught three regressions before release."]},{"role":"Web Developer (Part-time)","org":"University IT Office","dates":"2024 – Present","points":["Maintain the university''s public site in a CMS with hand-written HTML, CSS, and JavaScript.","Fixed 20+ accessibility issues to meet WCAG AA, improving audit scores across key pages."]}]}},{"id":"b5","type":"projects","label":"Projects","enabled":true,"data":{"items":[{"name":"Kubernetes Homelab","detail":"Three-node cluster running Docker services, provisioned with Terraform on AWS and deployed by a GitHub Actions CI/CD pipeline."},{"name":"Draftly","detail":"Block-based resume editor with drag-and-drop sections and application tracking. React, TypeScript, Supabase.","url":"github.com/jachen/draftly"}]}},{"id":"b3","type":"skills","label":"Skills","enabled":true,"data":{"groups":[{"name":"Cloud & DevOps","items":"AWS, Kubernetes, Terraform, GitHub Actions, Linux"},{"name":"Tools","items":"Git, Docker, Supabase, Postgres"},{"name":"Languages","items":"TypeScript, Python, Java, SQL"}]}},{"id":"b4","type":"education","label":"Education","enabled":true,"data":{"items":[{"school":"University of Texas at Arlington","degree":"B.S. Computer Science","dates":"Expected May 2027","detail":"Relevant coursework: Software Engineering, Databases, Computer Networks."}]}}]}'::jsonb, 1)
)
insert into public.resume_versions (user_id, resume_id, label, snapshot, created_at)
select
  me.id,
  (select id from live),
  v.label,
  case when (select id from live) is null then v.snapshot
       else jsonb_set(v.snapshot, '{id}', to_jsonb((select id from live)::text)) end,
  now() - make_interval(days => v.days_ago)
from me cross join versions v
where not exists (
  select 1 from public.resume_versions s where s.user_id = me.id and s.label = v.label
)
returning label;
